import { createCapabilityGraph, type IGraphNodeId } from '@migaia/capability/graph'

const serviceId = 'service' as IGraphNodeId
const graph = createCapabilityGraph()
graph.register({
  id: serviceId, kind: 'service', dependencies: [],
  start: () => ({ value: { read: () => 42 }, release: () => undefined })
})
try {
  await graph.ready()
  console.log(graph.readValue<{ read(): number }>(serviceId)?.read()) // 42
} finally {
  await graph.dispose()
}

const graph = createCapabilityGraph({ onError: (error) => console.error(error) })
const provider = 'provider' as IGraphNodeId
graph.register({
  id: provider,
  kind: 'service',
  dependencies: [],
  start: () => ({ value: { ready: true }, release: () => undefined })
})
const consumer = 'consumer' as IGraphNodeId
graph.register({
  id: consumer,
  kind: 'consumer',
  dependencies: [{ provider, required: true }],
  start: ({ get }) => ({ value: get(provider), release: () => undefined })
})
await graph.ready()
const service = graph.get<{ readonly ready: boolean }>(consumer, provider)
await graph.dispose()

